import { afterEach, describe, it, vi, expect } from 'vitest';

describe('repro: ref re-invocation on re-render', () => {
  afterEach(cleanup);

  it('stable ref callback is not re-invoked when the slotted element re-renders', () => {
    const handleRef = vi.fn();
    const Wrapper = ({ text }: { text: string }) => (
      <Slot ref={handleRef}>
        <button type="button">{text}</button>
      </Slot>
    );
    const { rerender } = render(<Wrapper text="a" />);
    const initialCalls = handleRef.mock.calls.length;
    rerender(<Wrapper text="b" />);
    console.log('initial ref calls:', initialCalls, 'after rerender:', handleRef.mock.calls.length);
    expect(handleRef).toHaveBeenCalledTimes(initialCalls);
  });

  it('does not hit maximum update depth when ref callback updates state', () => {
    const Comp = () => {
      const [count, setCount] = React.useState(0);
      const ref = React.useCallback((node: HTMLButtonElement | null) => {
        if (node) setCount((c) => c + 1);
      }, []);
      return (
        <Slot ref={ref}>
          <button type="button" data-count={count}>
            hi
          </button>
        </Slot>
      );
    };
    render(<Comp />);
    expect(screen.getByRole('button')).toHaveAttribute('data-count', '1');
  });
});

