import * as React from 'react';
import { cleanup, render, screen } from '@testing-library/react';
import { afterEach, describe, it, vi, expect } from 'vitest';
import {
  Menu,
  MenuTrigger,
  MenuPortal,
  MenuContent,
  MenuSub,
  MenuSubTrigger,
  MenuSubContent,
  MenuItem,
} from './menu';

describe('MenuSubTrigger ref stability', () => {
  afterEach(cleanup);

  it('does not re-invoke a stable ref callback when the sub trigger re-renders', () => {
    const handleRef = vi.fn();
    const Wrapper = ({ label }: { label: string }) => (
      <Menu.Root defaultOpen>
        <MenuTrigger>Open</MenuTrigger>
        <MenuPortal>
          <MenuContent>
            <MenuSub>
              <MenuSubTrigger ref={handleRef}>{label}</MenuSubTrigger>
              <MenuPortal>
                <MenuSubContent>
                  <MenuItem>Sub item</MenuItem>
                </MenuSubContent>
              </MenuPortal>
            </MenuSub>
            <MenuItem>Item</MenuItem>
          </MenuContent>
        </MenuPortal>
      </Menu.Root>
    );

    const { rerender } = render(<Wrapper label="a" />);
    expect(handleRef).toHaveBeenCalledTimes(1);
    expect(handleRef).toHaveBeenCalledWith(screen.getByText('a'));

    rerender(<Wrapper label="b" />);
    expect(handleRef).toHaveBeenCalledTimes(1);
  });
});

